写入采用「同目录临时文件 + 原子替换」：目标位置要么是旧内容，要么是新内容，
不会出现半个文件。
"""

import os
import shutil
from collections import namedtuple

from . import manifest, planner
from .errors import ApplyFailed

ApplyResult = namedtuple("ApplyResult", "operation product version applied deferred")

TMP_SUFFIX = ".winstall-part"


def _ensure_parent(path):
    parent = os.path.dirname(path)
    if parent:
        os.makedirs(parent, exist_ok=True)


def _put_file(source, destination):
    """把 ``source`` 放到 ``destination``（原子替换）。"""
    temporary = destination + TMP_SUFFIX
    shutil.copyfile(source, temporary)
    os.replace(temporary, destination)


def _delete_file(path):
    if os.path.isfile(path):
        os.remove(path)


def _cleanup_tmp_files(root, product):
    """清理产品目录下的所有临时文件。"""
    from . import layout
    payload = layout.payload_dir(root, product)
    if not os.path.isdir(payload):
        return
    for dirpath, _dirnames, filenames in os.walk(payload):
        for name in filenames:
            if name.endswith(TMP_SUFFIX):
                try:
                    os.remove(os.path.join(dirpath, name))
                except OSError:
                    pass


def _backup_file(path):
    """备份文件内容，返回临时文件路径；文件不存在返回 None。"""
    if not os.path.isfile(path):
        return None
    import tempfile
    fd, tmp = tempfile.mkstemp(prefix="winstall-backup-", suffix=".tmp")
    try:
        with os.fdopen(fd, 'wb') as out:
            with open(path, 'rb') as inp:
                shutil.copyfileobj(inp, out)
        return tmp
    except:
        try:
            os.remove(tmp)
        except OSError:
            pass
        raise


def _restore_file(backup_path, destination):
    """从备份恢复文件。"""
    if backup_path is None:
        # 文件原本不存在，删除它
        _delete_file(destination)
    else:
        # 恢复旧内容
        _put_file(backup_path, destination)


def apply_transaction(plan):
    """顺序执行 ``plan`` 中的动作，然后更新清单。

    如果文件被占用，记录到 deferred 并继续；
    如果遇到不可恢复的错误，回滚所有已更改的文件并抛出 ApplyFailed。
    """
    # 读取当前清单和产品状态
    data = manifest.read_manifest(plan.root)
    current_entry = manifest.get_product(data, plan.product)

    # 检查是否有待替换的文件（上次被占用的）
    pending = set()
    if current_entry:
        pending = set(current_entry.get("pending_replace") or [])

    # 执行动作，记录备份和结果
    applied = []
    deferred = []
    backups = {}  # {target_path: backup_path or None}
    created = []  # 本次新建的文件

    try:
        for action in plan.actions:
            target = planner.destination(plan, action)

            if action.kind == "write":
                # 先备份（如果存在）
                backup = None
                try:
                    if os.path.exists(target):
                        if os.path.isdir(target):
                            # 目标是目录，无法延迟，必须回滚
                            raise ApplyFailed(
                                action=action.relpath,
                                message=f"cannot replace directory: {action.relpath}"
                            )
                        backup = _backup_file(target)
                    backups[target] = backup

                    # 写入新内容
                    _ensure_parent(target)
                    _put_file(action.source, target)

                    applied.append(action.relpath)
                    if backup is None:
                        created.append(target)

                except PermissionError:
                    # 文件被占用，延迟处理
                    deferred.append(action.relpath)
                    # 恢复备份（如果有）
                    if backup:
                        try:
                            os.remove(backup)
                        except OSError:
                            pass
                    backups.pop(target, None)

            elif action.kind == "remove":
                # 删除文件前先备份
                backup = _backup_file(target) if os.path.isfile(target) else None
                backups[target] = backup
                try:
                    _delete_file(target)
                    applied.append(action.relpath)
                except PermissionError:
                    # 文件被占用，延迟删除
                    deferred.append(action.relpath)
                    if backup:
                        try:
                            os.remove(backup)
                        except OSError:
                            pass
                    backups.pop(target, None)

            else:
                raise ValueError("unknown action: %r" % (action.kind,))

        # 所有动作执行完毕（或延迟），更新清单
        if plan.operation == planner.INSTALL:
            manifest.set_product(data, plan.product, plan.version, plan.files, deferred)
        else:
            manifest.drop_product(data, plan.product)
        manifest.write_manifest(plan.root, data)

        # 清理备份文件
        for backup in backups.values():
            if backup:
                try:
                    os.remove(backup)
                except OSError:
                    pass

        # 清理临时文件
        _cleanup_tmp_files(plan.root, plan.product)

        return ApplyResult(plan.operation, plan.product, plan.version,
                          tuple(applied), tuple(deferred))

    except ApplyFailed:
        # ApplyFailed 已经是我们想要的异常，直接传播，但先回滚
        _rollback(plan, backups, created, data)
        raise

    except Exception as e:
        # 其他异常，回滚并包装成 ApplyFailed
        _rollback(plan, backups, created, data)
        raise ApplyFailed(message=str(e))


def _rollback(plan, backups, created, original_manifest):
    """回滚所有已更改的文件和清单。"""
    # 恢复所有备份的文件
    for target, backup in backups.items():
        try:
            _restore_file(backup, target)
        except OSError:
            pass
        # 清理备份文件
        if backup:
            try:
                os.remove(backup)
            except OSError:
                pass

    # 删除本次新建的文件
    for target in created:
        try:
            _delete_file(target)
        except OSError:
            pass

    # 恢复清单
    try:
        manifest.write_manifest(plan.root, original_manifest)
    except OSError:
        pass

    # 清理临时文件
    _cleanup_tmp_files(plan.root, plan.product)

