    """备份文件内容，返回临时文件路径；文件不存在返回 None。"""
    if not os.path.isfile(path):
        return None
    import tempfile
    fd, tmp = tempfile.mkstemp(prefix="winstall-backup-", suffix=".tmp")
    try:
        with os.fdopen(fd, 'wb') as out:
            with open(path, 'rb') as inp:
                shutil.copyfileobj(inp, out)
        return tmp
    except:
        try:
            os.remove(tmp)
        except OSError:
            pass
        raise


def _restore_file(backup_path, destination):
    """从备份恢复文件。"""
    if backup_path is None:
        # 文件原本不存在，删除它
        _delete_file(destination)
    else:
        # 恢复旧内容
        _put_file(backup_path, destination)


def apply_transaction(plan):
    """顺序执行 ``plan`` 中的动作，然后更新清单。

    如果文件被占用，记录到 deferred 并继续；
    如果遇到不可恢复的错误，回滚所有已更改的文件并抛出 ApplyFailed。
    """
    # 读取当前清单和产品状态
    data = manifest.read_manifest(plan.root)
    current_entry = manifest.get_product(data, plan.product)

    # 检查是否有待替换的文件（上次被占用的）
    pending_set = set()
    if current_entry:
        pending_set = set(current_entry.get("pending_replace") or [])

    # 执行动作，记录备份和结果
    applied = []
    deferred = []
    backups = {}  # {target_path: backup_path or None}
    created = []  # 本次新建的文件

    try:
        for action in plan.actions:
            target = planner.destination(plan, action)
            relpath_key = action.relpath

            if action.kind == "write":
                # 先备份（如果存在）
                backup = None
                try:
                    if os.path.exists(target):
                        if os.path.isdir(target):
                            # 目标是目录，无法延迟，必须回滚
                            raise ApplyFailed(
                                action=action.relpath,
                                message=f"cannot replace directory: {action.relpath}"
                            )
                        backup = _backup_file(target)
                    backups[target] = backup

                    # 写入新内容
                    _ensure_parent(target)
                    _put_file(action.source, target)

                    applied.append(relpath_key)
                    if backup is None:
                        created.append(target)
                    # 如果这个文件之前在 pending 中，现在成功了，从 pending 移除
                    pending_set.discard(relpath_key)

                except PermissionError:
                    # 文件被占用，延迟处理
                    deferred.append(relpath_key)
                    pending_set.add(relpath_key)
                    # 恢复备份（如果有）
                    if backup:
                        try:
                            os.remove(backup)
                        except OSError:
                            pass
                    backups.pop(target, None)

