                    _delete_file(target)
                    applied.append(relpath_key)
                except PermissionError:
                    # 文件被占用，延迟删除
                    deferred.append(relpath_key)
                    pending_set.add(relpath_key)
                    if backup:
                        try:
                            os.remove(backup)
                        except OSError:
                            pass
                    backups.pop(target, None)

            else:
                raise ValueError("unknown action: %r" % (action.kind,))

        # 所有动作执行完毕（或延迟），更新清单
        if plan.operation == planner.INSTALL:
            manifest.set_product(data, plan.product, plan.version, plan.files, 
                               sorted(pending_set))
        else:
            manifest.drop_product(data, plan.product)
        manifest.write_manifest(plan.root, data)

        # 清理备份文件
        for backup in backups.values():
            if backup:
                try:
                    os.remove(backup)
                except OSError:
                    pass

        # 清理临时文件
        _cleanup_tmp_files(plan.root, plan.product)

        return ApplyResult(plan.operation, plan.product, plan.version,
                          tuple(applied), tuple(deferred))

    except ApplyFailed:
        # ApplyFailed 已经是我们想要的异常，直接传播，但先回滚
        _rollback(plan, backups, created, data)
        raise

    except Exception as e:
        # 其他异常，回滚并包装成 ApplyFailed
        _rollback(plan, backups, created, data)
        raise ApplyFailed(message=str(e))


def _rollback(plan, backups, created, original_manifest):
    """回滚所有已更改的文件和清单。"""
    # 恢复所有备份的文件
    for target, backup in backups.items():
        try:
            _restore_file(backup, target)
        except OSError:
            pass
        # 清理备份文件
        if backup:
            try:
                os.remove(backup)
            except OSError:
                pass

    # 删除本次新建的文件
    for target in created:
        try:
            _delete_file(target)
        except OSError:
            pass

    # 恢复清单
    try:
        manifest.write_manifest(plan.root, original_manifest)
    except OSError:
        pass

    # 清理临时文件
    _cleanup_tmp_files(plan.root, plan.product)
